function distribute(cookies, k) {
  let distribution = new Array(k).fill(0);
  let minMax = Infinity;
  function backtrack(idx) {
    if (idx === cookies.length) {
      minMax = Math.min(minMax, Math.max(...distribution));
      return;
    }
    for (let i = 0; i < k; i++) {
      distribution[i] += cookies[idx];
      if (distribution[i] < minMax) backtrack(idx + 1);
      distribution[i] -= cookies[idx];
    }
  }
  backtrack(0);
  return minMax;
}
